### 2.2 React Error Boundaries

- Implement Error Boundaries to catch and handle runtime errors
- Place Error Boundaries strategically to isolate failing components
- Provide fallback UIs for graceful degradation

```tsx
'use client';

import { Component, ErrorInfo, ReactNode } from 'react';

interface ErrorBoundaryProps {
    fallback: ReactNode;
    children: ReactNode;
}

interface ErrorBoundaryState {
    hasError: boolean;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
    constructor(props: ErrorBoundaryProps) {
        super(props);
        this.state = { hasError: false };
    }

    static getDerivedStateFromError(_: Error): ErrorBoundaryState {
        return { hasError: true };
    }

    componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
        // Log the error to your monitoring service
        console.error('ErrorBoundary caught an error:', error, errorInfo);
    }

    render(): ReactNode {
        if (this.state.hasError) {
            return this.props.fallback;
        }

        return this.props.children;
    }
}

// Usage
export function ErrorFallback() {
    return (
        <div className="error-container">
            <h2>Something went wrong</h2>
            <button onClick={() => window.location.reload()}>Refresh the page</button>
        </div>
    );
}

// In a parent component
export function MyComponent() {
    return (
        <ErrorBoundary fallback={<ErrorFallback />}>
            <ComponentThatMightError />
        </ErrorBoundary>
    );
}
```

