### 3.1 Component Error Handling

- Use try-catch blocks for handling synchronous errors in event handlers
- Use error states to display appropriate error messages
- Implement error recovery mechanisms where appropriate

```tsx
'use client';

import { useState } from 'react';

export function DataProcessor() {
    const [error, setError] = useState<string | null>(null);
    const [data, setData] = useState<any>(null);

    const processData = (rawData: any) => {
        try {
            // Code that might throw an error
            const processed = JSON.parse(rawData);
            setData(processed);
            setError(null);
        } catch (err) {
            setError(
                `Failed to process data: ${err instanceof Error ? err.message : 'Unknown error'}`
            );
            // Log the detailed error
            console.error('Data processing error:', err);
        }
    };

    return (
        <div>
            {error && <div className="error-message">{error}</div>}
            {data && <div className="data-display">{/* Display data */}</div>}
            <button onClick={() => processData('{"key": "value"}')}>Process Data</button>
        </div>
    );
}
```

