### 3.2 API Request Error Handling

- Handle network errors and API errors separately
- Implement proper status code handling
- Use frameworks like React Query for consistent error handling

```tsx
'use client';

import { useQuery } from '@tanstack/react-query';
import axios from 'axios';

interface ApiError {
    message: string;
    status: number;
}

async function fetchUserData(userId: string) {
    try {
        const response = await axios.get(`/api/users/${userId}`);
        return response.data;
    } catch (error) {
        if (axios.isAxiosError(error)) {
            const status = error.response?.status || 500;
            const message = error.response?.data?.message || error.message;

            throw {
                message,
                status,
            } as ApiError;
        }
        throw { message: 'Unknown error occurred', status: 500 } as ApiError;
    }
}

export function UserProfile({ userId }: { userId: string }) {
    const {
        data: userData,
        error,
        isLoading,
        isError,
    } = useQuery({
        queryKey: ['user', userId],
        queryFn: () => fetchUserData(userId),
    });

    if (isLoading) {
        return <div>Loading user data...</div>;
    }

    if (isError) {
        const apiError = error as ApiError;

        if (apiError.status === 404) {
            return <div>User not found. Please check the user ID and try again.</div>;
        }

        return <div>Error loading user data: {apiError.message}</div>;
    }

    return (
        <div>
            <h1>{userData.name}</h1>
            {/* Rest of the component */}
        </div>
    );
}
```

