### 3.3 Form Validation Errors

- Use form libraries like React Hook Form or Formik for consistent form validation
- Display field-specific error messages inline
- Provide form-level error messages for submission errors

```tsx
'use client';

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const loginSchema = z.object({
    email: z.string().email('Please enter a valid email address'),
    password: z.string().min(8, 'Password must be at least 8 characters'),
});

type LoginFormData = z.infer<typeof loginSchema>;

export function LoginForm() {
    const [serverError, setServerError] = useState<string | null>(null);

    const {
        register,
        handleSubmit,
        formState: { errors },
    } = useForm<LoginFormData>({
        resolver: zodResolver(loginSchema),
    });

    const onSubmit = async (data: LoginFormData) => {
        try {
            setServerError(null);
            const response = await fetch('/api/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data),
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.message || 'Login failed');
            }

            // Handle successful login
        } catch (error) {
            setServerError(error instanceof Error ? error.message : 'An unknown error occurred');
        }
    };

    return (
        <form onSubmit={handleSubmit(onSubmit)} className="login-form">
            {serverError && <div className="server-error">{serverError}</div>}

            <div className="form-group">
                <label htmlFor="email">Email</label>
                <input id="email" {...register('email')} />
                {errors.email && <p className="field-error">{errors.email.message}</p>}
            </div>

            <div className="form-group">
                <label htmlFor="password">Password</label>
                <input id="password" type="password" {...register('password')} />
                {errors.password && <p className="field-error">{errors.password.message}</p>}
            </div>

            <button type="submit">Login</button>
        </form>
    );
}
```

