### 6.1 Client-Side Logging

- Implement a centralized error logging service
- Include relevant context with error logs
- Filter sensitive information before logging

```tsx
// utils/errorLogger.ts
export function logClientError(error: unknown, context?: Record<string, any>) {
    // Extract useful information from the error
    const errorInfo = {
        message: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined,
        context: {
            url: window.location.href,
            userAgent: navigator.userAgent,
            ...context,
        },
        timestamp: new Date().toISOString(),
    };

    // Remove sensitive information
    if (errorInfo.context && errorInfo.context.user) {
        delete errorInfo.context.user.password;
        delete errorInfo.context.user.token;
    }

    // Log to console in development
    if (process.env.NODE_ENV === 'development') {
        console.error('Client error:', errorInfo);
    }

    // Send to error tracking service
    try {
        fetch('/api/error-logging', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(errorInfo),
        }).catch((e) => console.error('Failed to send error log:', e));
    } catch (e) {
        console.error('Failed to log error:', e);
    }
}
```

